// JUNTAR MENSAJES + CONTEXTO DEL ANUNCIO
// 1) Une lo que el cliente escribió durante la ventana del buffer.
// 2) Busca si viene de un anuncio de Meta y, si es así, se lo cuenta a María.

// ---------- 1. Mensajes del buffer ----------
const filas = $input.all()
  .map(i => i.json)
  .filter(f => f && f.texto)
  .sort((a, b) => Number(a.id) - Number(b.id));

const texto = filas.map(f => String(f.texto).trim()).filter(Boolean).join('\n');
const fallback = $('Variables').first().json.texto_cliente || '';
const textoCliente = texto || fallback;

// ---------- 2. Contexto del anuncio ----------
// Busca en cualquier parte del payload, sin dar por hecho la estructura exacta.
function buscarClave(obj, clave, profundidad) {
  profundidad = profundidad || 0;
  if (!obj || typeof obj !== 'object' || profundidad > 8) return null;
  if (obj[clave]) return obj[clave];
  for (const k of Object.keys(obj)) {
    const r = buscarClave(obj[k], clave, profundidad + 1);
    if (r) return r;
  }
  return null;
}

let contexto = '';
let origen = 'ninguno';

try {
  // El v3 buscaba externalAdReply dentro del payload de Evolution.
  // La Cloud API ya nos da la atribución normalizada, así que armamos
  // la misma forma que espera buscarClave() y el resto sigue igual.
  const _v = $('Variables').first().json;
  const body = _v.ad_titulo
    ? { externalAdReply: { title: _v.ad_titulo, body: _v.ad_cuerpo || '' } }
    : {};

  // a) Anuncio de Meta (click-to-WhatsApp)
  const anuncio = buscarClave(body, 'externalAdReply');
  if (anuncio) {
    const partes = [anuncio.title, anuncio.body].filter(Boolean);
    if (partes.length) {
      contexto = partes.join(' — ');
      origen = 'anuncio';
    }
  }

  // b) Respondió citando nuestro saludo automático
  if (!contexto) {
    const citado = buscarClave(body, 'quotedMessage');
    if (citado) {
      const t = citado.conversation
             || (citado.extendedTextMessage && citado.extendedTextMessage.text)
             || (citado.imageMessage && citado.imageMessage.caption);
      if (t) { contexto = String(t); origen = 'saludo citado'; }
    }
  }
} catch (e) {
  contexto = '';
  origen = 'error: ' + e.message;
}

// ---------- 3. Lo que ve María ----------
// El contexto solo se inyecta si existe. Si no, va el mensaje pelado.
const textoParaMaria = contexto
  ? ('[CONTEXTO: este cliente llega desde este anuncio o saludo: "'
      + contexto.slice(0, 300) + '"]\n\n' + textoCliente)
  : textoCliente;

return [{
  json: {
    texto_acumulado: textoCliente,
    texto_para_maria: textoParaMaria,
    contexto_anuncio: contexto,
    origen_contexto: origen,
    mensajes_unidos: filas.length,
    numero_cliente: $('Variables').first().json.numero_cliente,
    nombre_cliente: $('Variables').first().json.nombre_cliente
  }
}];

// AÑADIR CONTEXTO  (+ saneado de entrada)
// Antepone al mensaje del cliente el saludo automático de la campaña.
// IMPORTANTE: primero limpia el texto del cliente de cualquier marcador
// interno. Si no, un cliente puede escribir [CONTEXTO: ...] o [PEDIDO]
// y María lo interpretaría como instrucción del sistema.

const base = $('Juntar mensajes').first().json;

// ---------- SANEADO ----------
function sanear(t) {
  return String(t || '')
    // marcadores internos que solo el sistema puede emitir
    .replace(/\[\s*\/?\s*(CONTEXTO|PEDIDO|PEDIDO_COMPLETO|FOTO|FOTO_OFERTA|ESCALAR)\b[^\]]*\]/gi, '')
    // corchetes sueltos que imiten la sintaxis
    .replace(/\[\/?[A-Z_]{4,}\s*:?[^\]]{0,80}\]/g, '')
    // intentos clásicos de reescribir el rol
    .replace(/^\s*(system|assistant|developer)\s*:/gim, '')
    .trim();
}

// Techo de longitud: un mensaje enorme dispara el coste por tokens
const MAX = 1500;
let textoCliente = sanear(base.texto_acumulado);
if (textoCliente.length > MAX) textoCliente = textoCliente.slice(0, MAX) + ' […]';

// ---------- CONTEXTO ----------
let contexto = '';
let origen = 'ninguno';

try {
  const fila = $('Leer contexto').first().json;
  if (fila && fila.texto) { contexto = String(fila.texto); origen = 'saludo automatico'; }
} catch (e) {}

if (!contexto && base.contexto_anuncio) {
  contexto = base.contexto_anuncio;
  origen = base.origen_contexto || 'webhook';
}

// El contexto también se sanea: viene de un mensaje, no de nosotros
contexto = sanear(contexto).replace(/\s+/g, ' ').slice(0, 300);

// Fichas de presentación ya enviadas a este cliente
let yaEnviadas = '';
try { yaEnviadas = String($('Variables').first().json.fichas || '').trim(); } catch (e) {}
const avisoFichas = yaEnviadas
  ? ('[FICHAS_YA_ENVIADAS: ' + yaEnviadas + ']\n')
  : '';

const textoParaMaria = contexto
  ? (avisoFichas + '[CONTEXTO: este cliente llega desde este anuncio o saludo: "'
      + contexto + '"]\n\n' + textoCliente)
  : (avisoFichas ? avisoFichas + '\n' + textoCliente : textoCliente);

return [{
  json: {
    ...base,
    texto_acumulado: textoCliente,
    contexto_detectado: contexto,
    origen_contexto: origen,
    texto_para_maria: textoParaMaria
  }
}];

// PREPARAR CATÁLOGO - convierte las filas de productos en texto para María
// Lee todos los items del nodo 'Leer Catálogo', filtra los activos, y arma un texto ordenado.

const items = $('Leer Catálogo').all();
let catalogo = '=== CATÁLOGO DE PRODUCTOS DISPONIBLES ===\n\n';
let contador = 0;

for (const item of items) {
  const p = item.json;
  // Solo productos activos
  if (String(p.activo).trim().toUpperCase() !== 'SI') continue;
  contador++;

  catalogo += `PRODUCTO ${contador} (id: ${p.id})\n`;
  catalogo += `Nombre: ${p.nombre}\n`;
  catalogo += `Palabras que usa el cliente: ${p.palabras_clave}\n`;
  catalogo += `Precio: $${p.precio}`;
  if (p.precio_antes && String(p.precio_antes) !== String(p.precio)) {
    catalogo += ` (antes $${p.precio_antes})`;
  }
  catalogo += `\n`;

  // OFERTA: si el campo trae algo, María DEBE mencionarla al dar el precio.
  //         Si está vacío, dice solo el precio y nada más.
  if (p.ofertas && String(p.ofertas).trim()) {
    const lista = String(p.ofertas).split('|').map(o => o.trim()).filter(Boolean);
    catalogo += `>>> ESTE PRODUCTO TIENE OFERTA. ES OBLIGATORIO MENCIONARLA\n`;
    catalogo += `>>> SIEMPRE QUE DIGAS EL PRECIO, SIN EXCEPCIÓN:\n`;
    for (const o of lista) catalogo += `>>>   * ${o}\n`;
  } else {
    catalogo += `>>> ESTE PRODUCTO NO TIENE OFERTA.\n`;
    catalogo += `>>> Di únicamente el precio de arriba. NO inventes ninguna promoción,\n`;
    catalogo += `>>> ni descuento por cantidad, ni envío especial, ni regalo.\n`;
  }

  catalogo += `Beneficios: ${p.beneficios}\n`;
  catalogo += `Descripción: ${p.descripcion}\n`;
  if (p.colores) catalogo += `Colores: ${p.colores}\n`;
  if (p.entrega) catalogo += `Entrega: ${p.entrega}\n`;
  if (p.info_extra) catalogo += `Info adicional: ${p.info_extra}\n`;
  catalogo += `Foto (señal para enviarla): [FOTO:${p.id}]\n`;
  if (p.ficha_texto && String(p.ficha_texto).trim()) {
    catalogo += `>>> Este producto TIENE ficha de presentación: [FICHA:${p.id}]\n`;
  }
  catalogo += `\n---\n\n`;
}

if (contador === 0) {
  catalogo += '(No hay productos activos en este momento.)\n';
}

return [{ json: { catalogo_texto: catalogo } }];

// ¿TOCA FICHA?  — decisión determinista, sin llamar al modelo
//
// Se envía la ficha si se cumplen las TRES condiciones:
//   1. El cliente no ha recibido ya la ficha de ese producto
//   2. Se identifica el producto: por el mensaje del cliente O por el
//      saludo automático del anuncio de Meta
//   3. Es una consulta general (precio, info, entrega, pago...) o el
//      cliente muestra intención de pedir

function normalizar(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // quita acentos
    .replace(/[^a-z0-9ñ\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const base = $('Juntar mensajes').first().json;
const mensaje = normalizar(base.texto_acumulado);

// Contexto: hay DOS fuentes posibles y se revisan las dos.
//  a) el saludo automático de la campaña (guardado en contexto_cliente)
//  b) el anuncio de Meta que viene en el propio webhook (externalAdReply:
//     título y texto del anuncio). A menudo el saludo es genérico pero el
//     anuncio sí nombra el producto.
let contextoSaludo = '';
let contextoAnuncio = '';
try { contextoSaludo = normalizar($('Añadir contexto').first().json.contexto_detectado); } catch (e) {}
try { contextoAnuncio = normalizar($('Juntar mensajes').first().json.contexto_anuncio); } catch (e) {}
const contexto = (contextoSaludo + ' ' + contextoAnuncio).trim();

// ---------- fichas que este cliente ya recibió ----------
let yaEnviadas = [];
try {
  yaEnviadas = String($('Variables').first().json.fichas || '')
    .split(',').map(s => s.trim()).filter(Boolean);
} catch (e) {}

// ---------- ¿qué quiere? ----------
const consultaGeneral = [
  'precio', 'precios', 'cuanto', 'cuanto cuesta', 'cuanto vale', 'cuanto sale',
  'costo', 'cuesta', 'vale', 'valor',
  'info', 'informacion', 'informes', 'detalles',
  'me interesa', 'interesa', 'quiero saber', 'quiero informacion',
  'cuenteme', 'cuentame', 'cuenteme mas', 'digame',
  'como funciona', 'para que sirve', 'de que se trata', 'como es',
  'promocion', 'promociones', 'oferta', 'ofertas', 'descuento',
  'envio', 'envios', 'entrega', 'mandan', 'hacen envio', 'hacen envios', 'llega',
  'cuanto tarda', 'cuanto tarda la entrega',
  'pago', 'pagar', 'se paga', 'como se paga', 'forma de pago', 'metodo de pago',
  'disponible', 'disponibilidad', 'tienen', 'hay'
];

// Intención de pedir: también merece ver la ficha antes de dar sus datos
const intencionPedir = [
  'quiero ordenar', 'quiero pedir', 'quiero comprar', 'quiero uno', 'quiero dos',
  'ordenar ya', 'pedir ya', 'lo quiero', 'la quiero', 'me lo llevo',
  'como lo pido', 'como hago el pedido', 'como ordeno', 'quisiera pedir'
];

let esGeneral = consultaGeneral.some(f => mensaje.includes(f))
             || intencionPedir.some(f => mensaje.includes(f));

// Saludo suelto o mensaje muy corto, cuando el anuncio ya dice el producto
const muyCorto = mensaje.split(' ').length <= 4;

// ---------- ¿qué producto? ----------
// Primero en el mensaje del cliente. Si no aparece, en el contexto del anuncio.
// Devuelve TODOS los productos que coinciden, con la longitud de la
// palabra clave que los identificó. Si coincide más de uno, hay duda.
// MODO ESTRICTO (para saludo y anuncio): solo valen las palabras clave
// COMPUESTAS, de dos palabras o más ("mini luces", "soporte inteligente").
// Una palabra suelta como "luces", "soporte" o "carga" aparece por
// casualidad en cualquier texto publicitario y provoca falsos positivos.
//
// MODO NORMAL (para el mensaje del cliente): vale cualquier palabra clave,
// porque la gente escribe "cepillo" o "sporte" a secas.
function buscarProductos(texto, minLargo, estricto) {
  const encontrados = [];
  if (!texto) return encontrados;
  for (const item of $('Leer Catálogo').all()) {
    const fila = item.json;
    if (String(fila.activo).trim().toUpperCase() !== 'SI') continue;
    if (!String(fila.ficha_texto || '').trim()) continue;
    const id = String(fila.id).trim();
    if (yaEnviadas.includes(id)) continue;

    let claves = String(fila.palabras_clave || '')
      .split(',').map(s => normalizar(s)).filter(s => s.length >= minLargo);

    // El nombre completo del producto siempre vale: es único de ese producto.
    const nombreCompleto = normalizar(fila.nombre);
    if (nombreCompleto.length >= minLargo) claves.push(nombreCompleto);

    if (estricto) {
      // Solo expresiones de DOS PALABRAS O MÁS
      claves = claves.filter(k => k.split(' ').length >= 2);
    } else {
      // Mensaje del cliente: también las palabras largas del nombre
      claves.push(...nombreCompleto.split(' ').filter(s => s.length >= 6));
    }

    let largo = 0;
    for (const clave of claves) {
      if (clave && texto.includes(clave) && clave.length > largo) largo = clave.length;
    }
    if (largo > 0) encontrados.push({ fila, largo });
  }
  return encontrados.sort((a, b) => b.largo - a.largo);
}

// --- 1) El mensaje del cliente manda ---
let producto = null;
let origen = 'ninguno';

const enMensaje = buscarProductos(mensaje, 4, false);   // mensaje: modo normal
if (enMensaje.length === 1 ||
    (enMensaje.length > 1 && enMensaje[0].largo > enMensaje[1].largo)) {
  producto = enMensaje[0].fila;
  origen = 'mensaje';
}

// --- 2) Si no, los contextos, con criterio estricto ---
// Se prueba cada fuente por separado (el anuncio de Meta suele ser la
// que nombra el producto aunque el saludo sea genérico).
// Solo vale si identifica UN producto sin ninguna duda. Si es genérico
// o encaja con varios, NO se envía ficha: María preguntará.
if (!producto) {
  // Se consulta cada fuente y se anotan los candidatos.
  // El SALUDO va primero: es nuestra propia plantilla y nombra el producto
  // de forma explícita. El anuncio del webhook es secundario.
  const candidatos = [];
  for (const [nombreFuente, fuente] of [['saludo', contextoSaludo], ['anuncio', contextoAnuncio]]) {
    if (!fuente) continue;
    const enCtx = buscarProductos(fuente, 6, true);         // contexto: modo estricto
    if (enCtx.length === 1 && enCtx[0].largo >= 6) {
      candidatos.push({ fuente: nombreFuente, id: String(enCtx[0].fila.id).trim(), fila: enCtx[0].fila });
    }
  }

  // Si dos fuentes señalan productos DISTINTOS, hay contradicción:
  // no se envía ninguna ficha. María preguntará qué producto le interesa.
  const idsDistintos = [...new Set(candidatos.map(x => x.id))];
  if (idsDistintos.length > 1) {
    return [{ json: {
      enviar_ficha: false,
      motivo: 'contradiccion entre fuentes: ' + candidatos.map(x => x.fuente + '=' + x.id).join(' / ')
    } }];
  }
  if (candidatos.length > 0) {
    producto = candidatos[0].fila;
    origen = candidatos[0].fuente;
  }
}

// ---------- decisión ----------
const enviar = Boolean(producto) && (esGeneral || muyCorto || origen === 'anuncio');

if (!enviar) {
  return [{ json: {
    enviar_ficha: false,
    _saludo: contextoSaludo.slice(0, 200),
    _anuncio: contextoAnuncio.slice(0, 200),
    motivo: producto ? 'no es consulta general' : 'producto no identificado con seguridad'
  } }];
}

const imagen = (producto.ficha_url && String(producto.ficha_url).trim())
             || (producto.foto_url  && String(producto.foto_url).trim())
             || '';
const texto = String(producto.ficha_texto).trim();

if (!imagen) return [{ json: { enviar_ficha: false, motivo: 'sin imagen en el catalogo' } }];

return [{
  json: {
    enviar_ficha: true,
    id_producto: String(producto.id).trim(),
    origen_producto: origen,
    _saludo: contextoSaludo.slice(0, 200),
    _anuncio: contextoAnuncio.slice(0, 200),
    imagen,
    texto,
    numero_cliente: ($('Variables').first().json.telefono_real
                 || $('Variables').first().json.numero_cliente)
  }
}];
